// Service worker for ComfyUI Mobile web push.
//
// Served from /mobile/sw.js (see the explicit route in __init__.py) so its scope
// covers the whole app. Its only job is to receive push messages and surface
// notifications even when the PWA isn't open — on iOS this only runs for a PWA
// that's been added to the Home Screen.

self.addEventListener('install', () => {
  // Take over without waiting for old tabs to close, so updates apply promptly.
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener('push', (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    payload = { title: 'ComfyUI Mobile', body: event.data ? event.data.text() : '' };
  }

  const title = payload.title || 'ComfyUI Mobile';
  const data = payload.data || {};
  const options = {
    body: payload.body || '',
    icon: '/mobile/icon-192.png',
    badge: '/mobile/icon-192.png',
    data,
    // Collapse repeats for the same prompt into one notification.
    tag: data.prompt_id || undefined,
  };
  // Opt-in preview thumbnail (data.image is a path on this server).
  if (data.image) {
    options.image = data.image;
  }

  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const target = (event.notification.data && event.notification.data.url) || '/mobile/';
  event.waitUntil(
    (async () => {
      // Notification payloads are generated by this server, but stay
      // same-origin — and keep the tap working — even if a malformed payload
      // reaches the worker (new URL throws on garbage like 'http://[').
      let targetUrl = new URL('/mobile/', self.location.origin);
      try {
        const candidate = new URL(target, self.location.origin);
        if (candidate.origin === self.location.origin) {
          targetUrl = candidate;
        }
      } catch {
        // Fall through to the app root instead of dropping the tap.
      }
      const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      // Hand the deep link to an existing app window and focus it. Never
      // client.navigate() a live window: that is a full document navigation,
      // reloading the app and discarding its in-memory state (undo history,
      // unsaved edits). The page-side listener opens the prompt in place.
      for (const client of clients) {
        if (client.url.includes('/mobile') && 'focus' in client) {
          if ('postMessage' in client) {
            client.postMessage({ type: 'mobile-notification-click', url: targetUrl.href });
          }
          return client.focus();
        }
      }
      if (self.clients.openWindow) {
        return self.clients.openWindow(targetUrl.href);
      }
      return undefined;
    })(),
  );
});
